  // Red Hat uses only major version
  type = "redhat"
  urls.push(`https://security.access.redhat.com/data/oval/v2/RHEL${majorVersion}/rhel-${majorVersion}.oval.xml.bz2`);
} else if (type === "sles") {
  // Try minor → fallback → major
  urls.push(`https://ftp.suse.com/pub/projects/security/oval/suse.linux.enterprise.server.${majorVersion}-SP${minorVersion}.xml.bz2`);
  urls.push(`https://ftp.suse.com/pub/projects/security/oval/suse.linux.enterprise.server.${majorVersion}.xml.bz2`);
