function safeTrim(str) {
    return str ? str.replace(/\s+/g, " ").trim() : "";
};

function getHostInfo(html) {
    const hostInfo = {
        hostIP: "",
        hostName: "",
        osVersion: "",
        arch: ""
    };

    const patterns = {
        hostIP: /IP Address<\/td>\s*<td[^>]*>([^<]+)<\/td>/i,
        hostName: /Host Name<\/td>\s*<td[^>]*>([^<]+)<\/td>/i,
        osVersion: /OS Version<\/td>\s*<td[^>]*>([^<]+)<\/td>/i,
        arch: /Architecture<\/td>\s*<td[^>]*>([^<]+)<\/td>/i
    };

    for (const key in patterns) {
        const match = html.match(patterns[key]);

        if (match)
            hostInfo[key] = safeTrim(match[1]);
    }

    return hostInfo;
}

function getTableRows(html) {
    const rows = [];
    const trMatches = [...html.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];

    for (const tr of trMatches) {
        const trContent = tr[1];
        const tdMatches = [...trContent.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map(m => safeTrim(m[1]));

        if (tdMatches.length < 5)
            continue;

        const result = tdMatches[1];
        const classType = tdMatches[2];

        if (result !== "true")
            continue;

        const referenceHTML = tdMatches[3];

        const referenceMatches = [...referenceHTML.matchAll(
            />((?:RHSA|RHBA)-\d{4}:\d{4,5}|CVE-\d{4}-\d{4,7}|SUSE-(?:SU|RU|SLE|LTSS)-[\w:-]+)/g
        )].map(m => m[1]);

        const rhsa = referenceMatches.find(r => r.startsWith("RHSA") || r.startsWith("RHBA")) || "";
        const cves = referenceMatches.filter(r => r.startsWith("CVE"));
        const title = tdMatches[4] || "";
        let plugin = "";
        let updateInfo = "";
        let severity = "";
        const titleParts = title.split(":");

        if (titleParts.length >= 2) {
            plugin = titleParts.slice(1).join(":").trim().split(" ")[0];
            updateInfo = titleParts.slice(1).join(":").trim();
            const sevMatch = title.match(/\(([^)]+)\)/);
            severity = sevMatch ? safeTrim(sevMatch[1]).toLowerCase() : "";
        }

        rows.push({
            rhsa,
            cves,
            plugin,
            updateInfo,
            severity
        });
    }

    return rows;
}

function combineData(hostInfo, tableRows, ip) {
    return tableRows.flatMap(row => row.cves.map(cve => ({
        "CVE": cve,
        "Description": row.updateInfo,
        "severity": row.severity,
        "Host IPAddress": ip,
        "Host Name": hostInfo.hostName,
        "recommended_advisory": row.rhsa,
        "Package": "",
        "Package Version": "",
        "Package Path": "",
        "hasFix": "",
        "Fixed Version": "",
        "Score": ""
    })));
}

function convertToCSV(data) {
    if (!data.length)
        return "CVE,Description,severity,Host IPAddress,Host Name,recommended_advisory,Package,Package Version,Package Path,hasFix,Fixed Version,Score";

    const headers = Object.keys(data[0]);
    const lines = [headers.join(",")];

    data.forEach(row => {
        const line = headers.map(h => {
            const val = row[h] || "";
            return typeof val === "string" && val.includes(",") ? `"${val.replace(/"/g, "\"\"")}"` : val;
        }).join(",");

        lines.push(line);
    });

    return lines.join("\n");
}

function processHTMLToCSV(htmlContent, ip) {
    const hostInfo = getHostInfo(htmlContent);
    const tableRows = getTableRows(htmlContent);
    const combinedData = combineData(hostInfo, tableRows, ip);
    const csv = convertToCSV(combinedData);
    return csv;
}

