function processGrypeJSON(grypeJsonContent, hostIP, hostName) {
    if (!grypeJsonContent || grypeJsonContent.trim() === "") {
        console.log("Grype scan result is empty, returning empty array");
        return [];
    }

    let grypeData;

    try {
        grypeData = typeof grypeJsonContent === "string" ? JSON.parse(grypeJsonContent) : grypeJsonContent;
    } catch (e) {
        console.log("Failed to parse Grype JSON, returning empty array:", e.message);
        return [];
    }

    const mappedData = [];
    const matches = grypeData.matches || [];

    if (matches.length === 0) {
        console.log("No vulnerabilities found in Grype scan");
        return [];
    }

    for (const entry of matches) {
        const vul = entry.vulnerability || {};
        const matchDetails = (entry.matchDetails || [{}])[0];
        const artifact = entry.artifact || {};
        const metadata = artifact.metadata || {};
        const cvssArray = vul.cvss || [];
        const cvssMetrics = cvssArray.length > 0 ? (cvssArray[0].metrics || {}) : {};
        const exploitabilityScore = cvssMetrics.exploitabilityScore || "";
        const searchedBy = matchDetails.searchedBy || {};
        const packageInfo = searchedBy.package || {};
        const fix = vul.fix || {};
        const hasFix = fix.state === "fixed" ? "Y" : "N";
        const fixVersions = fix.versions || [];
        const fixedVersion = fixVersions.length > 0 ? fixVersions.sort()[0] : "";

        mappedData.push({
            "CVE": vul.id || "",
            "Description": vul.description || "",
            "severity": vul.severity || "",
            "Host IPAddress": hostIP,
            "Host Name": hostName,
            "recommended_advisory": "",
            "Package": packageInfo.name || "",
            "Package Version": packageInfo.version || "",
            "Package Path": metadata.virtualPath || "",
            "hasFix": hasFix,
            "Fixed Version": fixedVersion,
            "Score": exploitabilityScore
        });
    }

    return mappedData;
};

function parseCSVToArray(csvContent) {
    const lines = csvContent.trim().split("\n");

    if (lines.length === 0)
        return [];

    function parseCSVLine(line) {
        const result = [];
        let current = "";
        let inQuotes = false;

        for (let i = 0; i < line.length; i++) {
            const char = line[i];
            const nextChar = line[i + 1];

            if (char === "\"") {
                if (inQuotes && nextChar === "\"") {
                    current += "\"";
                    i++;
                } else {
                    inQuotes = !inQuotes;
                }
            } else if (char === "," && !inQuotes) {
                result.push(current);
                current = "";
            } else {
                current += char;
            }
        }

        result.push(current);
        return result;
    }

    const headers = parseCSVLine(lines[0]);
    const data = [];

    for (let i = 1; i < lines.length; i++) {
        if (!lines[i].trim())
            continue;

        const values = parseCSVLine(lines[i]);
        const obj = {};

        headers.forEach((header, index) => {
            obj[header] = values[index] || "";
        });

        data.push(obj);
    }

    return data;
}

function convertToCSV(data) {
    if (!data.length)
        return "CVE,Description,severity,Host IPAddress,Host Name,recommended_advisory,Package,Package Version,Package Path,hasFix,Fixed Version,Score";

    const headers = Object.keys(data[0]);
